{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "실행 계획에서 확인한 병목을 인덱스 추가 판단으로 연결할 수 있는지 확인한다. 신고 목록 조회 쿼리에 인덱스를 추가하는 것이 적절하다고 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓의 신고 목록 조회 쿼리는 3.2초가 걸렸으며, 지원자는 실행 계획에서 신고 테이블과 판매글 테이블을 매번 전체 조인하는 것을 확인했다.",
          "task": "지원자는 조회 조건에 맞는 인덱스를 추가했다.",
          "action": "실행 계획과 조회 조건에서 어떤 정보를 근거로 인덱스 추가를 택했는지 설명한다.",
          "result": "설명한 근거에서 인덱스 추가가 해당 쿼리의 병목 개선에 적절한 이유가 드러난다."
        },
        "expectedEvidence": [
          "신고 목록 조회 쿼리에 인덱스를 추가한 판단 근거",
          "그 판단을 뒷받침한 조회 조건이나 실행 계획의 정보"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리의 실행 계획을 살펴보셨을 때, 인덱스를 추가한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 간결하게 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "인덱스 추가를 택한 근거를 해당 쿼리의 조회 조건이나 실행 계획 정보와 구체적으로 연결한다.",
            "제시한 근거가 인덱스를 통해 불필요한 데이터 탐색이나 처리 부담을 줄일 수 있다는 판단을 타당하게 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "인덱스 추가를 택한 근거를 설명하지만 해당 쿼리의 정보와 연결하는 내용이 일부 부족하다.",
            "인덱스가 조회 속도에 도움이 된다는 방향은 타당하지만 병목에 적합했던 이유는 일반적인 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스를 추가했다는 조치나 속도가 빨라졌다는 결과만 반복하고 선택 근거를 설명하지 못한다.",
            "선택 근거가 쿼리의 병목과 무관하거나 인덱스의 작동 원리에 맞지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "추적한 장애 원인을 같은 장애의 재발 방지 판단으로 연결할 수 있는지 확인한다. 스케줄러 중복 실행 이후 배포 체크리스트에 스케줄러 항목을 넣은 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 알림 중복 발송 문의를 받았고, 지원자는 시간순으로 로그를 살펴 스케줄러가 서버 두 대에서 동시에 실행되는 것을 찾았다.",
          "task": "지원자는 배포 체크리스트에 스케줄러 항목을 넣었다.",
          "action": "스케줄러 항목을 배포 체크리스트에 넣어야 한다고 판단한 근거를 설명한다.",
          "result": "설명한 근거에서 체크리스트 항목 추가와 같은 장애의 재발 방지 사이의 연결이 드러난다."
        },
        "expectedEvidence": [
          "배포 체크리스트에 스케줄러 항목을 넣은 판단 근거",
          "그 판단을 뒷받침한 스케줄러 중복 실행의 재발 위험"
        ]
      },
      "question": "포켓마켓에서 로그로 스케줄러 중복 실행을 찾으셨을 때, 배포 체크리스트에 스케줄러 항목을 넣은 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 간결하게 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "스케줄러 항목을 배포 체크리스트에 넣은 근거를 중복 실행이 다시 발생할 위험과 구체적으로 연결한다.",
            "체크리스트 항목 추가가 같은 장애의 반복을 막는 데 적절한 이유를 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "재발 방지를 위해 스케줄러 항목을 넣었다고 설명하지만 중복 실행 위험과의 연결이 구체적이지 않다.",
            "배포 시 점검 누락을 줄인다는 취지는 타당하지만 스케줄러 항목이 필요했던 근거는 일반적인 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "체크리스트에 항목을 넣었다는 사실만 반복하고 추가한 근거를 설명하지 못한다.",
            "판단 근거가 스케줄러 중복 실행의 재발 방지와 무관하거나 당장의 오류 수정 설명에만 머문다."
          ]
        }
      }
    }
  ]
}

{
