      "interviewBlueprint": {
        "questionIntent": "요청의 목적과 범위를 요구사항 정의서로 구체화할 수 있는지 확인한다. 요구사항 정의서에 넣을 것과 뺄 것의 경계를 정한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰했다.",
          "task": "기획 담당으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "요구사항 정의서에 담을 범위를 정한 근거를 당시 요청의 목적과 제약에 연결해 설명한다.",
          "result": "설명한 근거가 요구사항의 포함·제외 경계를 뒷받침하는지 설명한다."
        },
        "expectedEvidence": [
          "요구사항 정의서에 담을 범위를 정한 근거",
          "포함·제외 판단을 뒷받침한 요청의 목적이나 제약"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰하셨을 때, 요구사항 정의서에 담을 범위를 정한 근거는 무엇이었나요?",
      "answerTip": "한 가지 사례를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "요구사항 정의서에 담을 범위를 정한 근거를 구체적인 요청의 목적이나 제약과 연결해 설명한다.",
            "제시한 근거로 무엇을 범위에 넣고 뺄지 일관되게 구분할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "범위를 정한 근거를 제시하지만 필요성이나 실현 가능성 같은 일반적인 설명에 머문다.",
            "포함·제외 경계는 드러나지만 그 경계를 뒷받침하는 정보가 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항 정의서를 작성했다는 사실이나 문서 내용만 나열하고 범위를 정한 근거를 설명하지 못한다.",
            "제시한 근거가 요구사항의 포함·제외 판단과 연결되지 않거나 서로 모순된다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 화면 단위의 기능 흐름으로 구체화할 수 있는지 확인한다. 예외 상황의 특성에 맞춰 화면 흐름을 설계한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "task": "기획 담당으로 Figma를 사용해 화면설계서를 작성했다.",
          "action": "예외 상황에 맞춰 화면 흐름을 설계한 근거를 해당 상황의 조건과 연결해 설명한다.",
          "result": "선택한 화면 흐름이 예외 상황에 부합하는 이유가 설명에서 드러난다."
        },
        "expectedEvidence": [
          "예외 상황에 맞춰 화면 흐름을 설계한 근거",
          "화면 흐름의 판단 근거가 된 예외 상황의 조건"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨을 때, 예외 상황에 맞춰 화면 흐름을 설계한 근거는 무엇이었나요?",
      "answerTip": "듣는 사람이 떠올릴 수 있게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황에 맞춰 화면 흐름을 설계한 근거를 구체적인 상황 조건과 연결해 설명한다.",
            "설명한 근거가 예외 상황에서 화면이 이어지는 흐름을 뒷받침하며 논리적으로 일관된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면 흐름을 설계한 근거를 제시하지만 사용자 편의 같은 일반적인 설명에 머문다.",
            "예외 상황과 화면 흐름의 연결은 드러나지만 이를 뒷받침하는 조건 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "화면 수나 도구 사용 경험만 설명하고 예외 상황의 화면 흐름을 설계한 근거를 제시하지 못한다.",
            "제시한 근거가 예외 상황과 연결되지 않거나 설명한 화면 흐름을 뒷받침하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 용량이 의심스러울 때 그대로 투약하지 않고 멈출 수 있는지 평가한다. 평소와 다른 용량을 투약 보류가 필요한 문제로 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 근무 중 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔다.",
          "task": "지원자는 투약 전에 용량이 이상하다고 느껴 투약을 멈췄다.",
          "action": "평소 용량과 처방 용량의 차이를 투약 보류의 근거로 삼은 이유를 설명한다.",
          "result": "처방 용량의 타당성을 확인하기 전에는 투약하지 않아야 한다고 판단한 이유를 설명한다."
        },
        "expectedEvidence": [
          "투약을 멈춰야 한다고 판단한 구체적인 근거",
          "평소와 다른 처방 용량이 투약 보류가 필요한 불확실성이라고 본 이유"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배로 들어왔을 때, 투약을 멈춰야 한다고 판단한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 간결하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소 용량과 처방 용량의 차이를 짚어 투약을 멈춘 판단 근거를 구체적으로 설명한다.",
            "용량 차이만으로 오류를 단정하지 않으면서도 처방의 타당성이 불확실한 상태에서 투약할 위험을 근거로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 용량이어서 투약을 멈췄다고 답하지만 용량 차이를 문제로 본 설명이 제한적이다.",
            "의심스러운 처방은 확인 전 투약하지 않아야 한다고 답하지만 당시 판단을 뒷받침하는 설명은 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 근거 대신 이후 입력 오류가 확인됐다는 결과만 반복한다.",
            "처방 용량에 의문이 있어도 처방대로 투약해야 한다고 주장하거나 투약 보류 판단과 무관한 내용으로 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태와 관련된 정보를 다음 근무자에게 빠짐없이 전달할 정보로 판단할 수 있는지 평가한다. 진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 선택한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "낙상 고위험 환자 인수인계 체크리스트 개선 활동에서 사고 보고서를 통해 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린다는 점을 확인했다.",
          "task": "지원자는 인수인계 체크리스트에 진통제 투여 시각과 보행 보조 여부를 넣자고 제안했다.",
          "action": "진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 선택한 근거를 설명한다.",
          "result": "두 항목이 다음 근무자의 환자 상태 파악에 필요한 정보라고 판단한 이유를 설명한다."
        },
        "expectedEvidence": [
          "진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 제안한 근거",
          "각 항목이 다음 근무자에게 필요한 환자 정보인 이유"
        ]
      },
      "question": "낙상 고위험 환자 인수인계 체크리스트 개선 활동에서, 인수인계 항목에 진통제 투여 시각과 보행 보조 여부를 넣자고 제안한 근거는 무엇이었나요?",
      "answerTip": "요점을 먼저 말하고 설명을 덧붙여 주세요.",
      "evaluationRubric": {
        "excellent": {
